    esg_score: Annotated[Optional[float], Field(description='ESG score in points (e.g. 0-100).')] = None,
    premium_per_point: Annotated[Optional[float], Field(description='Valuation premium per ESG point as a decimal.')] = None,
    esg_risk_score: Annotated[Optional[float], Field(description='ESG risk score in points (higher = riskier).')] = None,
    discount_per_point: Annotated[Optional[float], Field(description='Valuation discount per ESG risk point as a decimal.')] = None,
    n: Annotated[Optional[float], Field(description='Number of users or nodes in the network.')] = None,
    k: Annotated[Optional[int], Field(description='Number of events k for the Poisson probability P(X=k); integer ≥ 0.')] = None,
    data_volume: Annotated[Optional[float], Field(description='Volume of proprietary data held.')] = None,
